:root {
  --bg: #1b1b2f;
  --card: #26264a;
  --text: #f2f2f7;
  --muted: #a0a0c0;
  --accent: #ffd166;
  --bar: #7c7cff;
  --bar-highlight: #ffd166;
  --focus: #ffd166;
}

* {
  box-sizing: border-box;
}

[hidden] {
  display: none !important;
}

body {
  margin: 0;
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  background: var(--bg);
  color: var(--text);
  font-family: system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  font-size: 16px;
  line-height: 1.5;
  padding: 16px;
}

.card {
  background: var(--card);
  border-radius: 16px;
  padding: 24px;
  width: 100%;
  max-width: 640px;
  box-shadow: 0 12px 40px rgba(0, 0, 0, 0.4);
}

.card-header {
  text-align: center;
  margin-bottom: 24px;
}

h1 {
  margin: 0 0 4px;
  font-size: 1.75rem;
  letter-spacing: 0.5px;
}

.subtitle {
  margin: 0;
  color: var(--muted);
  font-size: 1rem;
}

.inputs {
  display: grid;
  grid-template-columns: repeat(7, minmax(0, 1fr));
  gap: 8px;
  margin-bottom: 24px;
}

.field {
  display: flex;
  flex-direction: column;
  align-items: stretch;
  gap: 6px;
}

.field label {
  font-size: 0.875rem;
  color: var(--muted);
  text-align: center;
}

.field input {
  width: 100%;
  min-width: 0;
  padding: 8px 4px;
  font-size: 1rem;
  text-align: center;
  color: var(--text);
  background: #1f1f3a;
  border: 2px solid #3a3a66;
  border-radius: 8px;
  transition: border-color 0.15s, background 0.15s;
}

.field input:hover {
  border-color: var(--bar);
}

.field input:focus-visible {
  outline: 3px solid var(--focus);
  outline-offset: 2px;
  border-color: var(--focus);
}

.field input:active {
  background: #2e2e55;
}

.chart-section {
  margin-bottom: 20px;
}

.chart {
  display: flex;
  align-items: flex-end;
  gap: 6px;
  height: 200px;
  padding: 8px;
  background: #1f1f3a;
  border-radius: 12px;
  border: 1px solid #3a3a66;
}

.bar-wrap {
  flex: 1 1 0;
  min-width: 0;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: flex-end;
  height: 100%;
}

.bar {
  width: 100%;
  max-width: 48px;
  background: var(--bar);
  border-radius: 4px 4px 0 0;
  transition: height 0.2s ease, background 0.2s;
  min-height: 2px;
}

.bar.highlight {
  background: var(--bar-highlight);
  box-shadow: 0 0 0 2px var(--bar-highlight) inset;
}

.bar-label {
  font-size: 0.75rem;
  color: var(--muted);
  margin-top: 4px;
  white-space: nowrap;
}

.chart-legend {
  display: flex;
  gap: 16px;
  justify-content: center;
  margin-top: 8px;
  font-size: 0.875rem;
  color: var(--muted);
}

.legend-item {
  display: inline-flex;
  align-items: center;
  gap: 6px;
}

.legend-swatch {
  width: 12px;
  height: 12px;
  border-radius: 3px;
  display: inline-block;
}

.legend-normal {
  background: var(--bar);
}

.legend-highlight {
  background: var(--bar-highlight);
}

.summary {
  text-align: center;
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.average {
  margin: 0;
  font-size: 1.125rem;
}

.average strong {
  color: var(--accent);
  font-size: 1.25rem;
}

.longest {
  margin: 0;
  font-size: 1rem;
  color: var(--bar-highlight);
}

@media (max-width: 480px) {
  .card {
    padding: 16px;
  }
  .inputs {
    gap: 4px;
  }
  .field label {
    font-size: 0.75rem;
  }
  .field input {
    padding: 6px 2px;
    font-size: 0.9375rem;
  }
  .chart {
    height: 160px;
    gap: 4px;
  }
}

(function () {
  'use strict';

  var DAYS = ['Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat', 'Sun'];
  var inputs = [];
  var chart = document.getElementById('chart');
  var averageValue = document.getElementById('average-value');
  var longestBadge = document.getElementById('longest-badge');
  var longestDay = document.getElementById('longest-day');

  for (var i = 0; i < 7; i++) {
    inputs.push(document.getElementById('day-' + i));
  }

  function clamp(value) {
    if (isNaN(value)) return 0;
    if (value < 0) return 0;
    if (value > 12) return 12;
    return value;
  }

  function getValues() {
    return inputs.map(function (input) {
      var raw = parseFloat(input.value);
      return clamp(raw);
    });
  }

  function render() {
    var values = getValues();
    var max = 0;
    var maxIndex = -1;

    for (var i = 0; i < values.length; i++) {
      if (values[i] > max) {
        max = values[i];
        maxIndex = i;
      }
    }

    chart.innerHTML = '';
    for (var j = 0; j < 7; j++) {
      var wrap = document.createElement('div');
      wrap.className = 'bar-wrap';

      var bar = document.createElement('div');
      bar.className = 'bar';
      if (j === maxIndex && max > 0) {
        bar.classList.add('highlight');
      }
      var heightPercent = (values[j] / 12) * 100;
      bar.style.height = heightPercent + '%';
      bar.setAttribute('aria-hidden', 'true');

      var label = document.createElement('span');
      label.className = 'bar-label';
      label.textContent = DAYS[j];

      wrap.appendChild(bar);
      wrap.appendChild(label);
      chart.appendChild(wrap);
    }

    var sum = values.reduce(function (a, b) { return a + b; }, 0);
    var avg = sum / 7;
    averageValue.textContent = avg.toFixed(1);

    if (max > 0) {
      longestBadge.hidden = false;
      longestDay.textContent = DAYS[maxIndex] + ' (' + max + ' h)';
    } else {
      longestBadge.hidden = true;
    }

    chart.setAttribute('aria-label', 'Bar chart of hours slept per day: ' + values.join(', '));
  }

  inputs.forEach(function (input) {
    input.addEventListener('input', render);
    input.addEventListener('change', render);
  });

  render();
})();
